## Proxy para validación

```javascript
function crearObjetoValidado(schema) {
  const datos = {};

  return new Proxy(datos, {
    set(target, prop, value) {
      const regla = schema[prop];
      if (regla && !regla.validar(value)) {
        throw new TypeError(`${prop}: ${regla.mensaje}`);
      }
      target[prop] = value;
      return true;
    }
  });
}

const usuario = crearObjetoValidado({
  edad: {
    validar: v => typeof v === 'number' && v >= 0 && v <= 150,
    mensaje: 'debe ser número entre 0 y 150',
  },
  email: {
    validar: v => /^[^@]+@[^@]+\.[^@]+$/.test(v),
    mensaje: 'formato inválido',
  },
});

usuario.nombre = 'Ana';       // Sin validación — ok
usuario.email = 'ana@test.com'; // OK
usuario.edad = 200;          // TypeError: edad: debe ser número entre 0 y 150
```

