## Proxy para valores por defecto

```javascript
function conDefecto(defecto) {
  return new Proxy({}, {
    get(target, prop) {
      return prop in target ? target[prop] : defecto;
    }
  });
}

const config = conDefecto('sin configurar');
config.host = 'localhost';

console.log(config.host);    // 'localhost'
console.log(config.timeout); // 'sin configurar' (no está definido)
```

