// Proxy reactivo — similar a como funciona Vue 3
function reactivo(obj, onChange) {
  return new Proxy(obj, {
    set(target, prop, value) {
      const anterior = target[prop];
      target[prop] = value;
      if (anterior !== value) {
        onChange(prop, value, anterior);
      }
      return true;
    },
    get(target, prop, receiver) {
      const valor = Reflect.get(target, prop, receiver);
      // Si el valor es un objeto, lo envolvemos también en proxy
      if (typeof valor === 'object' && valor !== null) {
        return reactivo(valor, onChange);
      }
      return valor;
    },
  });
}

const estado = reactivo(
  { nombre: 'Ana', config: { tema: 'claro' } },
  (prop, nuevo, anterior) => {
    console.log(`Cambio: ${prop} ${anterior} → ${nuevo}`);
  }
);

estado.nombre = 'Bob';           // Cambio: nombre Ana → Bob
estado.config.tema = 'oscuro';   // Cambio: tema claro → oscuro

// Proxy para API REST tipada (type-safe builder)
function crearCliente(baseUrl) {
  function construirRuta(partes) {
    return new Proxy({}, {
      get(_, prop) {
        // Métodos HTTP:
        if (['get', 'post', 'put', 'delete'].includes(prop)) {
          return async (data) => {
            const url = baseUrl + '/' + partes.join('/');
            console.log(`${prop.toUpperCase()} ${url}`, data ? JSON.stringify(data) : '');
            return { ok: true, url, method: prop, data };
          };
        }
        // Continúa construyendo la ruta:
        return construirRuta([...partes, prop]);
      }
    });
  }
  return construirRuta([]);
}

const api = crearCliente('https://api.ejemplo.com');

const r = await api.usuarios['123'].pedidos.get();
console.log(r.url); // 'https://api.ejemplo.com/usuarios/123/pedidos'

await api.productos.post({ nombre: 'Nuevo producto' });

