function conDefecto(obj, valorDefecto) {
  return new Proxy(obj, {
    get(target, prop) {
      return prop in target ? target[prop] : valorDefecto;
    }
  });
}

const config = conDefecto({ host: 'localhost', port: 3000 }, 'no configurado');

const hostVal = config.host;
const timeoutVal = config.timeout;
const portVal = config.port;
const unknownVal = config.unknownProp;

console.log(hostVal, timeoutVal, portVal, unknownVal);

function soloLectura(obj) {
  return new Proxy(obj, {
    set(target, prop) {
      throw new TypeError('El objeto es de solo lectura');
    },
    deleteProperty(target, prop) {
      throw new TypeError('El objeto es de solo lectura');
    },
    get(target, prop, receiver) {
      return Reflect.get(target, prop, receiver);
    },
  });
}

const original = { x: 10, y: 20 };
const inmutable = soloLectura(original);

const xVal = inmutable.x;

let escrituraFalla = false;
try {
  inmutable.x = 99;
} catch (e) {
  escrituraFalla = e instanceof TypeError;
}

let borradoFalla = false;
try {
  delete inmutable.y;
} catch (e) {
  borradoFalla = e instanceof TypeError;
}

console.log(xVal, escrituraFalla, borradoFalla);
console.log('original.x todavía:', original.x); // 10 — sin cambios

function crearModelo(schema) {
  const datos = {};

  return new Proxy(datos, {
    set(target, prop, value) {
      const regla = schema[prop];

      if (regla) {
        if (typeof value !== regla.tipo) {
          throw new TypeError(`${prop}: se esperaba ${regla.tipo}, recibido ${typeof value}`);
        }
        if (regla.tipo === 'number') {
          if (regla.min !== undefined && value < regla.min) {
            throw new TypeError(`${prop}: mínimo es ${regla.min}`);
          }
          if (regla.max !== undefined && value > regla.max) {
            throw new TypeError(`${prop}: máximo es ${regla.max}`);
          }
        }
      }

      target[prop] = value;
      return true;
    },
    get(target, prop, receiver) {
      return Reflect.get(target, prop, receiver);
    },
  });
}

const usuario = crearModelo({
  nombre: { tipo: 'string' },
  edad:   { tipo: 'number', min: 0, max: 150 },
  activo: { tipo: 'boolean' },
});

usuario.nombre = 'Ana'; // OK
usuario.edad = 30;       // OK
usuario.activo = true;   // OK
usuario.extra = 'libre'; // OK — no está en schema

const nombreVal = usuario.nombre;
const edadVal = usuario.edad;

let errorTipo = false;
try {
  usuario.edad = 'treinta'; // TypeError: número esperado
} catch (e) {
  errorTipo = e instanceof TypeError;
}

let errorRango = false;
try {
  usuario.edad = 200; // TypeError: máximo 150
} catch (e) {
  errorRango = e instanceof TypeError;
}

console.log(nombreVal, edadVal, errorTipo, errorRango);
